sys_variable_value.value:
(function (outputs, steps, params, stepResult, assertEqual) {
    var DT1 = gs.getProperty('x_snc_sas_positi_0.dt_request_requirement');
    var api = new sn_dt.DecisionTableAPI();

    // The documented read pattern does NOT work: the object getDecisions()
    // returns is a snapshot whose result_elements reads back as an empty
    // string. Take sys_id, re-query, then read through the container.
    function basisFor(exempt, overCap, trigger) {
        var resp = api.getDecisions(DT1, { exempt: exempt, over_cap: overCap, itf_trigger: trigger });
        if (!resp || !resp.length || !resp[0].sys_id) { return '(no matching row)'; }
        var ans = new GlideRecord('sys_decision_multi_result');
        if (!ans.get(resp[0].sys_id.toString())) { return '(answer record missing)'; }
        var v = '';
        try { v = ans.result_elements.request_basis.toString(); } catch (e) { v = ''; }
        return v || '(answer has no value)';
    }

    describe('ITF Request Requirement decision table', function () {
        it('has its sys_id published in the dt_request_requirement property', function () {
            expect(DT1).toBeTruthy();
        });
        it('treats an exemption as decisive regardless of the other inputs', function () {
            expect(basisFor(true, false, false)).toBe('not_required');
            expect(basisFor(true, true, true)).toBe('not_required');
        });
        it('requires both bases when over cap and an ITF trigger coincide', function () {
            expect(basisFor(false, true, true)).toBe('both');
        });
        it('requires only the hiring freeze basis when over cap alone', function () {
            expect(basisFor(false, true, false)).toBe('hiring_freeze');
        });
        it('requires only the intent to fill basis when an ITF trigger alone', function () {
            expect(basisFor(false, false, true)).toBe('intent_to_fill');
        });
        it('requires nothing when no condition applies', function () {
            expect(basisFor(false, false, false)).toBe('not_required');
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
